  const box=document.createElement('section');box.className='chart';host.appendChild(box);
  const key=(row,names)=>names.find(k=>Object.hasOwn(row,k)),num=v=>Number(String(v??'').trim()),peak=(a,k)=>a.reduce((m,z)=>z[k]>m[k]?z:m,a[0]),pct=(a,b)=>100*Math.abs(a-b)/Math.max(Math.abs(a),1e-12),area=(a,k)=>a.slice(1).reduce((s,z,i)=>s+(z[k]+a[i][k])*(z.t-a[i].t)/2,0),interp=(a,t,k)=>{for(let i=1;i<a.length;i++)if(t<=a[i].t){const p=a[i-1],q=a[i],r=(t-p.t)/(q.t-p.t);return p[k]+r*(q[k]-p[k]);}return a.at(-1)[k];};
