  function render(){const t=tr();box.innerHTML=`<h3>${t.title}</h3><p class="meta">${t.lead}</p><div class="twocol"><div><label>${t.ref}</label><select id="crossReference"><option value="current">${t.current}</option><option value="A-005">${t.bench} A-005</option><option value="B-005">${t.bench} B-005</option><option value="C-005">${t.bench} C-005</option><option value="D-005">${t.bench} D-005</option></select></div><div><label>${t.source}</label><select id="crossSource"><option>HEC-HMS</option><option>SWMM</option></select></div></div><div class="twocol"><div><label>${t.basis}</label><select id="crossScale"><option value="raw">${t.raw}</option><option value="scaled">${t.scaled}</option></select></div><div><label>${t.interval} <span id="crossUnit">${t.second}</span></label><input id="crossInterval" type="number" min="0.001" step="0.001" value="60"></div></div><label>${t.file}</label><input id="crossFile" type="file" accept=".csv,.txt,text/csv,text/plain"><p class="meta">${t.format}</p><p class="meta">${t.guide} <a href="cross-model-benchmarks.zip" download>${t.download}</a></p><button class="report" id="crossRun">${t.run}</button><div class="status hide" id="crossOut"></div>`;box.querySelector('#crossScale').addEventListener('change',e=>{const scaled=e.target.value==='scaled';box.querySelector('#crossInterval').value=scaled?'1':'60';box.querySelector('#crossUnit').textContent=scaled?t.minute:t.second;});box.querySelector('#crossRun').addEventListener('click',compare);}
