  async function compare(){const t=tr(),out=box.querySelector('#crossOut'),file=box.querySelector('#crossFile').files[0];try{const selected=box.querySelector('#crossReference').value;if(!file||(!last&&selected==='current'))throw Error(t.missing);const scaled=box.querySelector('#crossScale').value==='scaled',interval=num(box.querySelector('#crossInterval').value);if(!(interval>0))throw Error(t.invalid);const src=parse(await file.text()),f=src[0],tk=key(f,scaled?['model_time_min','time_min','time']:['time_s','time','t']),qk=key(f,scaled?['scaled_outflow_m3_s','outflow_m3_s','qout','qo']:['outflow_m3_s','qout','qo','outflow']),hk=key(f,['relative_head_m','h','stage','water_level_m']),sk=key(f,['incremental_storage_m3','s','storage','storage_m3']),ik=key(f,scaled?['scaled_inflow_m3_s','inflow_m3_s','qin','qi']:['inflow_m3_s','qin','qi','inflow']);if(!tk||!qk)throw Error(t.invalid);const ext=src.map(r=>({t:scaled?num(r[tk])*15:num(r[tk]),qo:scaled?num(r[qk])*240:num(r[qk]),h:hk?num(r[hk]):null,s:sk?num(r[sk]):null,qi:ik?(scaled?num(r[ik])*240:num(r[ik])):null})).filter(r=>Number.isFinite(r.t)&&Number.isFinite(r.qo));const ref=selected==='current'?last.r.rows:await publicReference(selected);if(ext.length<2||ext.some((r,i)=>i&&r.t<=ext[i-1].t)||ext[0].t>ref[0].t||ext.at(-1).t<ref.at(-1).t)throw Error(t.invalid);const fit=ref.map(r=>({t:r.t,qo:interp(ext,r.t,'qo')})),e=fit.map((r,i)=>r.qo-ref[i].qo),mean=ref.reduce((s,r)=>s+r.qo,0)/ref.length,rmse=Math.sqrt(e.reduce((s,v)=>s+v*v,0)/e.length),mae=e.reduce((s,v)=>s+Math.abs(v),0)/e.length,den=ref.reduce((s,r)=>s+(r.qo-mean)**2,0),nse=den?1-e.reduce((s,v)=>s+v*v,0)/den:null,pr=peak(ref,'qo'),pe=peak(ext,'qo'),qe=pct(pr.qo,pe.qo),te=Math.abs(pr.t-pe.t),ve=pct(area(ref,'qo'),area(fit,'qo')),hasH=hk&&ext.every(r=>Number.isFinite(r.h)),hasS=sk&&ext.every(r=>Number.isFinite(r.s)),relH=hk==='relative_head_m',relS=sk==='incremental_storage_m3',he=hasH?pct(peak(ref,'h').h-(relH?ref[0].h:0),peak(ext,'h').h):null,se=hasS?pct(peak(ref,'s').s-(relS?ref[0].s:0),peak(ext,'s').s):null,hasI=ik&&ext.every(r=>Number.isFinite(r.qi)),ce=hasI&&hasS?area(ext,'qi')-area(ext,'qo')-(ext.at(-1).s-ext[0].s):null,threshold=scaled?interval*15:interval,complete=Boolean(hasS),pass=complete&&qe<=.5&&te<=threshold&&se<=.5,result={reference:selected,external_model:box.querySelector('#crossSource').value,basis:scaled?'laboratory_time_scaled_240':'direct_engineering_units',assessment:complete?(pass?'pass':'fail'):'outflow_comparison_only',records_compared:ref.length,outflow_rmse_m3_s:rmse,outflow_mae_m3_s:mae,outflow_nse:nse,peak_outflow_error_percent:qe,peak_time_error_s:te,total_outflow_volume_error_percent:ve,maximum_head_error_percent:he,maximum_storage_error_percent:se,external_continuity_residual_m3:ce,pass},v=(x,u='%')=>x===null?t.na:x.toFixed(3)+u,headline=complete?(pass?t.pass:t.warn):t.partial;out.className='status '+(pass?'':'warn');out.innerHTML=`<strong>${t.result} — ${headline}</strong><table class="metrics"><tr><th>${t.records}</th><td>${ref.length}</td></tr><tr><th>${t.rmse}</th><td>${v(rmse,' m³/s')}</td></tr><tr><th>${t.mae}</th><td>${v(mae,' m³/s')}</td></tr><tr><th>${t.nse}</th><td>${nse===null?t.na:nse.toFixed(5)}</td></tr><tr><th>${t.q}</th><td>${v(qe)}</td></tr><tr><th>${t.time}</th><td>${te.toFixed(2)} s</td></tr><tr><th>${t.volume}</th><td>${v(ve)}</td></tr><tr><th>${t.h}</th><td>${v(he)}</td></tr><tr><th>${t.s}</th><td>${v(se)}</td></tr><tr><th>${t.balance}</th><td>${v(ce,' m³')}</td></tr></table><p class="meta">${t.note}</p><button class="report" id="crossDownload">${t.record}</button>`;out.querySelector('#crossDownload').addEventListener('click',()=>download(result));}catch(error){out.className='status stop';out.innerHTML='<strong>'+t.failed+'</strong>'+error.message;}}
  // Normalize each comparison to the same event origin.  The routing core retains
